document.addEventListener("DOMContentLoaded",function(){var n=document.getElementsByClassName("captcha-image")[0],i=n.getAttribute("src"),t=document.getElementsByClassName("captcha-input")[0],r=document.getElementsByClassName("refresh-icon")[0],u=function(){t.value="";var r=i+"?t="+Date.now();n.setAttribute("src",r)};n.addEventListener("load",function(){t.focus()});r.addEventListener("click",u)});